11		"github.com/hmdsefi/faultline/kernel"
12		"github.com/hmdsefi/faultline/kernel/fault"
13	)
14	
15	const (
16		ttl        = 100 * time.Millisecond
17		renewEvery = 90 * time.Millisecond
18		timeout    = 50 * time.Millisecond
19		backoff    = 10 * time.Millisecond
20		think      = 60 * time.Millisecond
21		duration   = 7 * time.Second
22		clientStop = duration - 500*time.Millisecond
23	
24		crashEvery     = 2 * time.Second
25		crashMin       = 10 * time.Millisecond
26		crashMax       = 300 * time.Millisecond
27		partitionEvery = 700 * time.Millisecond
28		partitionMin   = 250 * time.Millisecond
29		partitionMax   = 450 * time.Millisecond
30	)
31	
32	var keys = []string{"k1", "k2"}
33	
34	// appends is the percent of operations that are appends, per client: c1 mostly reads.
35	var appends = []int{10, 50}
36	
37	var leaseOptions = faultline.Options{Seeds: 100, Duration: duration}
38	
39	func TestLeaseKV(t *testing.T) { faultline.Run(t, leaseOptions, leaseWorld) }
40	
41	// leaseWorld builds one world: the lock, the store, servers s1 and s2, and clients c1 and c2.
42	// The fault plan crashes s1, s2 or the store, one at a time, and splits the network in two with
43	// s1 and s2 on different sides.
44	func leaseWorld(w *faultline.World) {
45		lock := w.AddServer("lock", (&leasekv.Lock{W: w, TTL: ttl}).Boot)
46		st := &leasekv.Store{W: w}
47		store := w.AddServer("store", st.Boot)
48		var servers []kernel.NodeID
