108			}
109			if c.values[k] == nil {
110				c.values[k] = map[string]bool{}
111			}
112			for _, v := range list[c.listed[k]:] {
113				if c.values[k][v] {
114					return fmt.Errorf("key %s holds %s twice", k, v)
115				}
116				c.values[k][v] = true
